# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM HUKUKUNUN DELİLLERİ (EDİLLE-İ ŞER\'İYYE) GENEL TABLOSU</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ASLİ DELİLLER (EDİLLE-İ ERBAA)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• 1. Kitap (Kur\'an-ı Kerim): Birinci ve ana kaynak (Nas)</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• 2. Sünnet: Hz. Peygamber\'in (sav) söz, fiil ve takrirleri</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• 3. İcma: Müçtehitlerin şer\'i bir hükümde görüş birliği</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• 4. Kıyas: Ortak illete dayalı akli-içtihadi hüküm çıkarma</text>\n  <text x="35" y="184" font-size="11.2" font-weight="bold" fill="#1e40af">• Kitap ve Sünnet \'Nas\' (Vahiy kaynaklı naklî delil) sayılır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">FER\'Î (TÂLİ / YARDIMCI) DELİLLER</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• İstihsan: Kıyas-ı celîden daha güçlü bir delile yönelme</text>\n  <text x="370" y="110" font-size="11.2" fill="#14532d">• İstıslah (Mesâlih-i Mürsele): Kamu yararı (maslahat)</text>\n  <text x="370" y="132" font-size="11.2" fill="#14532d">• Örf ve Âdet: Toplumun İslam\'a aykırı olmayan geleneği</text>\n  <text x="370" y="154" font-size="11.2" fill="#14532d">• Sedd-i Zerâi: Kötülüğe giden yolları kapatma ilkesi</text>\n  <text x="370" y="176" font-size="11.2" fill="#14532d">• İstıshab, Sahabi Kavli ve Şer\'u Men Kablenâ</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Muâz bin Cebel hadisi deliller arasındaki başvuru sırasını (Kitap → Sünnet → İçtihat) ortaya koyar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BİRİNCİ ASLİ DELİL: KİTAP (KUR\'AN-I KERİM) VE HÜKÜM ÖZELLİKLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">KİTAP DELİLİNİN TEMEL NİTELİKLERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Lafzı ve manasıyla Allah kelamıdır; mütevatirdir.</text>\n  <text x="35" y="110" font-size="11.2" fill="#713f12">• Sübûtu (bize ulaşması) kesin (kat\'î) bir delildir.</text>\n  <text x="35" y="132" font-size="11.2" fill="#713f12">• Ahkâm Ayetleri: İbadet, aile, miras, ticaret ve ceza</text>\n  <text x="35" y="150" font-size="11.2" fill="#713f12">  hukukuna dair yaklaşık 500 fıkhi hüküm ayeti içerir.</text>\n  <text x="35" y="172" font-size="11.2" fill="#713f12">• Hükümler çoğunlukla küllî (genel ilke) ve mücmeldir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">KUR\'AN\'IN HÜKÜM KOYMA YÖNTEMİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• 1. Tedricilik: Hükümlerin aşama aşama indirilmesi</text>\n  <text x="370" y="110" font-size="11.2" fill="#581c87">• 2. Kolaylık (Yüsr) ve Sıkıntıyı Giderme (Adem-i Harac)</text>\n  <text x="370" y="132" font-size="11.2" fill="#581c87">• 3. Az Teklif (Kıllet-i Teklîf): Güç yetirilebilir sorumluluk</text>\n  <text x="370" y="154" font-size="11.2" fill="#581c87">• 4. Mekâsıdü\'ş-Şerîa: Dini, canı, aklı, nesli ve malı</text>\n  <text x="370" y="172" font-size="11.2" fill="#581c87">  koruma (zarûrât-ı diniyye) ve maslahatı gözetme</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kur\'an ayetlerinin sübûtu daima kat\'îdir; delâleti (anlama işaret etmesi) ise kat\'î veya zannî olabilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İKİNCİ ASLİ DELİL: SÜNNETİN ÇEŞİTLERİ VE KUR\'AN KARŞISINDAKİ KONUMU</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">MAHİYETİNE VE RİVAYETİNE GÖRE SÜNNET</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• Kavlî Sünnet: Hz. Peygamber\'in (sav) mübarek sözleri</text>\n  <text x="35" y="110" font-size="11.2" fill="#7c2d12">• Fiilî Sünnet: İbadet ve muamelat uygulamaları</text>\n  <text x="35" y="132" font-size="11.2" fill="#7c2d12">• Takrirî Sünnet: Gördüğü bir işi onaylaması/susması</text>\n  <text x="35" y="154" font-size="11.2" fill="#7c2d12">• Rivayet gücü: Mütevatir Sünnet, Meşhur Sünnet ve</text>\n  <text x="35" y="172" font-size="11.2" fill="#7c2d12">  Âhâd (Haber-i Vâhid) Sünnet olarak üçe ayrılır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">SÜNNETİN KUR\'AN İLE İLİŞKİSİ (BEYAN GÖREVİ)</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• 1. Teyit ve Tekit: Kur\'an\'daki hükmü pekiştirir.</text>\n  <text x="370" y="110" font-size="11.2" fill="#164e63">• 2. Beyan ve Tefsir: Mücmel (kapalı) ayeti açıklar</text>\n  <text x="370" y="128" font-size="11.2" fill="#164e63">  (Namazın rekâtları, haccın yapılışı, zekât nisapları).</text>\n  <text x="370" y="150" font-size="11.2" fill="#164e63">• 3. Takyid ve Tahsis: Mutlakı sınırlar, umumiyi özelleştirir.</text>\n  <text x="370" y="172" font-size="11.2" font-weight="bold" fill="#155e75">• 4. Teşri: Kur\'an\'da değinilmeyen konuda hüküm koyar.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«Beni nasıl namaz kılarken görüyorsanız siz de öyle namaz kılın!» hadisi Sünnetin beyan görevine örnektir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
